    private async Task<(bool Succeeded, string Code, decimal Value)> ValidateCurrencyAsync(FinanceRequestContext context, FinanceCompanyOption company, string currency, DateOnly date, decimal? rate, Guid? rateId, Guid? versionId, int? versionNumber, CancellationToken cancellationToken)
    {
        if (currency == company.FunctionalCurrencyCode) return rate is null or 1m && rateId is null && versionId is null && versionNumber is null ? (true, "eligible", 1m) : (false, "functional_currency_rate_must_be_explicit_one", 0m);
        if (rate is not > 0m || rateId is null || versionId is null || versionNumber is not > 0) return (false, "exact_exchange_rate_evidence_required", 0m); var record = await exchangeRates.FindExchangeRateAsync(context.TenantContext, rateId.Value, cancellationToken); var version = record?.Versions.SingleOrDefault(item => item.Id == versionId.Value && item.VersionNumber == versionNumber.Value); if (record is null || record.LifecycleState != MasterDataLifecycleState.Active || version is null || !string.Equals(record.SourceCurrencyCode, currency, StringComparison.OrdinalIgnoreCase) || !string.Equals(record.TargetCurrencyCode, company.FunctionalCurrencyCode, StringComparison.OrdinalIgnoreCase) || version.Rate != rate.Value || version.EffectiveFrom > date || version.EffectiveTo < date) return (false, "exchange_rate_evidence_mismatch", 0m); return (true, "eligible", rate.Value);
    }

    private async Task<(bool Succeeded, string Code, (DateOnly DueDate, FinancePaymentTermSnapshotRecord Snapshot)? Value)> ResolvePaymentTermAsync(FinanceRequestContext context, Guid? paymentTermId, DateOnly? dueDate, DateOnly documentDate, CancellationToken cancellationToken)
    {
        if (paymentTermId is null) return dueDate is { } explicitDate ? (true, "eligible", (explicitDate, null!)) : (false, "payment_term_not_configured", null);
        var term = await paymentTerms.FindPaymentTermAsync(context.TenantContext, paymentTermId.Value, cancellationToken); if (term is null || term.LifecycleState != MasterDataLifecycleState.Active) return (false, "payment_term_not_configured", null); var version = term.Versions.Where(item => item.EffectiveFrom <= documentDate && (item.EffectiveTo is null || item.EffectiveTo >= documentDate)).OrderByDescending(item => item.VersionNumber).FirstOrDefault(); if (version is null) return (false, "payment_term_not_configured", null); var baseDate = documentDate; var due = version.ScheduleMode == PaymentTermScheduleMode.SingleDueDate ? AddOffset(baseDate, version.DueOffset) : version.Installments.OrderBy(item => item.Sequence).Select(item => AddOffset(baseDate, item.Offset)).LastOrDefault(baseDate); if (dueDate is { } explicitDue && explicitDue != due) return (false, "payment_term_snapshot_mismatch", null); var snapshot = new FinancePaymentTermSnapshotRecord(term.Id, version.Code, version.Name.English, version.Name.Arabic, version.VersionNumber, version.Id, documentDate, due); return (true, "eligible", (due, snapshot));
    }

    private async Task<(string Code, FinancePostingRuleEntity? Value)> FindRuleAsync(FinanceDbContext db, Guid companyId, string contract, string eventName, DateOnly date, CancellationToken cancellationToken)
    { var rules = await db.PostingRules.Where(item => item.CompanyId == companyId && item.SourceContract == contract && item.SourceEvent == eventName && item.Lifecycle == FinancePostingRuleLifecycle.Enabled && item.EffectiveFrom <= date && (item.EffectiveTo == null || item.EffectiveTo >= date)).ToListAsync(cancellationToken); return rules.Count switch { 0 => ("pending_mapping", null), 1 => ("eligible", rules[0]), _ => ("ambiguous_mapping", null) }; }

    private async Task<(bool Succeeded, string Code, FinanceJournalRecord? Value)> CreatePostedJournalAsync(FinanceDbContext db, FinanceRequestContext context, Guid companyId, DateOnly date, string currency, decimal amount, decimal functionalAmount, decimal? exchangeRate, Guid? exchangeRateId, Guid? exchangeRateVersionId, int? exchangeRateVersionNumber, string sourceContract, string sourceEvent, Guid sourceEvidenceId, int sourceEvidenceVersion, FinancePostingRuleEntity rule, bool reverse, string description, CancellationToken cancellationToken)
    {
        var company = Company(context, companyId); if (company is null) return (false, "company_scope_denied", null); var period = await db.FiscalPeriods.Where(item => item.CompanyId == companyId && item.StartDate <= date && item.EndDate >= date).SingleOrDefaultAsync(cancellationToken); if (period is null) return (false, "period_not_configured", null); if (period.State != FinanceFiscalPeriodState.Open) return (false, period.State == FinanceFiscalPeriodState.SoftClosed ? "period_soft_closed" : "period_closed", null); var debitId = reverse ? rule.CreditAccountId : rule.DebitAccountId; var creditId = reverse ? rule.DebitAccountId : rule.CreditAccountId; var accounts = await db.Accounts.Where(item => item.CompanyId == companyId && (item.Id == debitId || item.Id == creditId)).ToDictionaryAsync(item => item.Id, cancellationToken); if (accounts.Count != 2 || accounts.Values.Any(item => !item.IsPostingAccount || item.Lifecycle != FinanceAccountLifecycle.Active || item.EffectiveFrom > date || item.EffectiveTo < date)) return (false, "account_not_postable", null); if (await db.Journals.AnyAsync(item => item.SourceContract == sourceContract && item.SourceEvidenceId == sourceEvidenceId && item.SourceEvidenceVersion == sourceEvidenceVersion, cancellationToken)) return (false, "source_effect_exists", null); var sequence = (await db.Journals.Where(item => item.CompanyId == companyId).Select(item => (long?)item.JournalSequence).MaxAsync(cancellationToken) ?? 0L) + 1L; var txCurrency = NormalizeCode(currency)!; var rate = txCurrency == company.FunctionalCurrencyCode ? 1m : exchangeRate!.Value; var command = new FinanceJournalCommand(companyId, date, date, txCurrency, rate, txCurrency == company.FunctionalCurrencyCode ? null : exchangeRateId, txCurrency == company.FunctionalCurrencyCode ? null : exchangeRateVersionId, txCurrency == company.FunctionalCurrencyCode ? null : exchangeRateVersionNumber, sourceContract, sourceEvent, sourceEvidenceId, sourceEvidenceVersion, rule.Id, description, [new FinanceJournalLineCommand(debitId, amount, 0m, amount, txCurrency, null, description), new FinanceJournalLineCommand(creditId, 0m, amount, amount, txCurrency, null, description)], Guid.NewGuid(), Guid.NewGuid().ToString("N"), Guid.NewGuid().ToString("N"), FinanceJournalAmountAuthority.ManualTransactionCurrency, FinanceApprovalRequirement.NotRequired); var journal = new FinanceJournalEntity(context.TenantId, command.Id, command, sequence, company.FunctionalCurrencyCode, context.ActorId, DateTimeOffset.UtcNow); journal.SetCorrelation(context.CorrelationId); journal.SetPeriod(period.FiscalYearId, period.Id); journal.SetRule(rule.Id, rule.VersionNumber); journal.SetStatus(FinanceJournalStatus.Posted, context.ActorId, DateTimeOffset.UtcNow); journal.Lines.Add(new FinanceJournalLineEntity(context.TenantId, Guid.NewGuid(), journal.Id, 1, accounts[debitId], command.Lines[0], null, reverse ? functionalAmount : functionalAmount, 0m, FinanceJournalAmountAuthority.ManualTransactionCurrency)); journal.Lines.Add(new FinanceJournalLineEntity(context.TenantId, Guid.NewGuid(), journal.Id, 2, accounts[creditId], command.Lines[1], null, 0m, functionalAmount, FinanceJournalAmountAuthority.ManualTransactionCurrency)); db.Journals.Add(journal); db.SourceEffects.Add(new FinanceSourceEffectEntity(context.TenantId, Guid.NewGuid(), companyId, sourceContract, sourceEvidenceId, sourceEvidenceVersion, journal.Id, DateTimeOffset.UtcNow)); return (true, "succeeded", ToJournal(journal));
    }

    private async Task<(bool Succeeded, string Code, FinanceJournalRecord? Value)> CreateReversalJournalAsync(FinanceDbContext db, FinanceRequestContext context, FinanceJournalEntity original, DateOnly postingDate, string reason, Guid commandId, CancellationToken cancellationToken)
    {
        var period = await db.FiscalPeriods.Where(item => item.CompanyId == original.CompanyId && item.StartDate <= postingDate && item.EndDate >= postingDate).SingleOrDefaultAsync(cancellationToken); if (period is null) return (false, "period_not_configured", null); if (period.State != FinanceFiscalPeriodState.Open) return (false, period.State == FinanceFiscalPeriodState.SoftClosed ? "period_soft_closed" : "period_closed", null); var accounts = await db.Accounts.Where(item => item.CompanyId == original.CompanyId && original.Lines.Select(line => line.AccountId).Contains(item.Id)).ToDictionaryAsync(item => item.Id, cancellationToken); if (accounts.Count != original.Lines.Select(line => line.AccountId).Distinct().Count() || accounts.Values.Any(item => !item.IsPostingAccount || item.Lifecycle != FinanceAccountLifecycle.Active)) return (false, "account_not_postable", null); var company = Company(context, original.CompanyId)!; var sequence = (await db.Journals.Where(item => item.CompanyId == original.CompanyId).Select(item => (long?)item.JournalSequence).MaxAsync(cancellationToken) ?? 0L) + 1L; var command = new FinanceJournalCommand(original.CompanyId, original.JournalDate, postingDate, original.TransactionCurrencyCode, original.ExchangeRate, original.ExchangeRateId, original.ExchangeRateVersionId, original.ExchangeRateVersionNumber, "finance-reversal.v1", "settlement-reversal", null, null, null, reason, original.Lines.OrderBy(item => item.LineNumber).Select(line => new FinanceJournalLineCommand(line.AccountId, line.Credit, line.Debit, line.TransactionAmount, line.TransactionCurrencyCode, line.CostCenterId, reason)).ToArray(), commandId, Guid.NewGuid().ToString("N"), Guid.NewGuid().ToString("N"), FinanceJournalAmountAuthority.ManualTransactionCurrency, FinanceApprovalRequirement.NotRequired); var reversal = new FinanceJournalEntity(context.TenantId, Guid.NewGuid(), command, sequence, company.FunctionalCurrencyCode, context.ActorId, DateTimeOffset.UtcNow); reversal.SetCorrelation(context.CorrelationId); reversal.LinkOriginal(original.Id); reversal.SetPeriod(period.FiscalYearId, period.Id); reversal.SetStatus(FinanceJournalStatus.Posted, context.ActorId, DateTimeOffset.UtcNow); foreach (var line in original.Lines.OrderBy(item => item.LineNumber)) { var account = accounts[line.AccountId]; reversal.Lines.Add(new FinanceJournalLineEntity(context.TenantId, Guid.NewGuid(), reversal.Id, line.LineNumber, account, new FinanceJournalLineCommand(line.AccountId, line.Credit, line.Debit, line.TransactionAmount, line.TransactionCurrencyCode, line.CostCenterId, reason), null, line.FunctionalCredit, line.FunctionalDebit, FinanceJournalAmountAuthority.ManualTransactionCurrency)); } db.Journals.Add(reversal); original.LinkReversal(reversal.Id); original.SetStatus(FinanceJournalStatus.Reversed, context.ActorId, DateTimeOffset.UtcNow); return (true, "succeeded", ToJournal(reversal));
    }

    private IQueryable<FinanceAllocationEntity> ActiveAllocations(FinanceDbContext db) => db.Allocations.Where(item => item.Status == FinanceAllocationStatus.Active && item.ReversalOfAllocationId == null && !db.Allocations.Any(reversal => reversal.ReversalOfAllocationId == item.Id));
    private async Task<bool> SupplierIsActiveAsync(FinanceRequestContext context, Guid id, CancellationToken cancellationToken) { var value = await suppliers.FindSupplierAsync(context.TenantContext, id, cancellationToken); return value is not null && value.TenantId.Value == context.TenantId.Value && value.LifecycleState == MasterDataLifecycleState.Active; }
    private async Task<bool> CustomerIsActiveAsync(FinanceRequestContext context, Guid id, CancellationToken cancellationToken) { var value = await customers.FindCustomerReferenceAsync(context.TenantContext, id, cancellationToken); return value is not null && value.TenantId.Value == context.TenantId.Value && value.LifecycleState == MasterDataLifecycleState.Active; }
    private FinanceCompanyOption? Company(FinanceRequestContext context, Guid id) { var matches = companies.List(context.TenantId).Where(item => item.CompanyId == id && item.IsActive).ToArray(); if (matches.Length == 0 || matches.Select(item => NormalizeCode(item.FunctionalCurrencyCode)).Distinct(StringComparer.OrdinalIgnoreCase).Count() != 1) return null; if (context.TenantContext.Scope is { } scope) { var value = scope.Value; if (value.StartsWith("Company:", StringComparison.OrdinalIgnoreCase) && (!Guid.TryParse(value["Company:".Length..], out var scoped) || scoped != id)) return null; if (value.StartsWith("Branch:", StringComparison.OrdinalIgnoreCase) && (!Guid.TryParse(value["Branch:".Length..], out var branch) || !matches.Any(item => item.BranchId == branch))) return null; } return matches[0] with { FunctionalCurrencyCode = NormalizeCode(matches[0].FunctionalCurrencyCode)! }; }
    private async Task<IReadOnlyList<FinanceOpenItemRecord>> ToOpenItemsAsync(FinanceDbContext db, IEnumerable<FinanceOpenItemEntity> entities, CancellationToken cancellationToken) { var result = new List<FinanceOpenItemRecord>(); foreach (var entity in entities) result.Add(await ToOpenItemAsync(db, entity, cancellationToken)); return result; }
    private async Task<FinanceOpenItemRecord> ToOpenItemAsync(FinanceDbContext db, FinanceOpenItemEntity entity, CancellationToken cancellationToken) { var allocated = await ActiveAllocations(db).Where(item => item.OpenItemId == entity.Id).SumAsync(item => (decimal?)item.Amount, cancellationToken) ?? 0m; var outstanding = Math.Max(0m, entity.OriginalAmount - allocated); var status = entity.RecognitionState != FinanceOpenItemRecognitionState.Recognized ? FinanceOpenItemStatus.OnHold : outstanding == 0m ? FinanceOpenItemStatus.Settled : allocated > 0m ? FinanceOpenItemStatus.PartiallySettled : FinanceOpenItemStatus.Open; var term = entity.PaymentTermId is { } id ? new FinancePaymentTermSnapshotRecord(id, entity.PaymentTermCode ?? string.Empty, entity.PaymentTermEnglishName, entity.PaymentTermArabicName, entity.PaymentTermVersionNumber ?? 0, entity.PaymentTermVersionId ?? Guid.Empty, entity.PaymentTermEffectiveOn ?? entity.DocumentDate, entity.DueDate) : null; return new(entity.Id, entity.TenantId.Value, entity.CompanyId, entity.Kind, entity.SupplierId, entity.CustomerId, entity.SourceContract, entity.SourceDocumentId, entity.SourceDocumentVersion, entity.SourceEvidenceId, entity.SourceEvidenceVersion, entity.Reference, entity.DocumentDate, entity.DueDate, entity.CurrencyCode, entity.OriginalAmount, entity.FunctionalCurrencyCode, entity.OriginalFunctionalAmount, entity.ExchangeRate, entity.ExchangeRateId, entity.ExchangeRateVersionId, entity.ExchangeRateVersionNumber, term, entity.MatchEvidenceId, entity.MatchEvidenceVersion, entity.RecognitionState, entity.RecognitionJournalId, allocated, outstanding, status, entity.Version); }
    private async Task<IReadOnlyList<FinanceSettlementDocumentRecord>> ToDocumentsAsync(FinanceDbContext db, IEnumerable<FinanceSettlementDocumentEntity> entities, CancellationToken cancellationToken) { var result = new List<FinanceSettlementDocumentRecord>(); foreach (var entity in entities) result.Add(await ToDocumentAsync(db, entity, cancellationToken)); return result; }
    private async Task<FinanceSettlementDocumentRecord> ToDocumentAsync(FinanceDbContext db, FinanceSettlementDocumentEntity entity, CancellationToken cancellationToken) { var allocated = await ActiveAllocations(db).Where(item => item.SettlementDocumentId == entity.Id).SumAsync(item => (decimal?)item.Amount, cancellationToken) ?? 0m; return new(entity.Id, entity.TenantId.Value, entity.CompanyId, entity.Status, entity.Direction, entity.SupplierId, entity.CustomerId, entity.CashAccountId, entity.PaymentMethodId, entity.DocumentDate, entity.CurrencyCode, entity.Amount, entity.FunctionalCurrencyCode, entity.FunctionalAmount, entity.ExchangeRate, entity.ExchangeRateId, entity.ExchangeRateVersionId, entity.ExchangeRateVersionNumber, entity.ExternalReference, entity.Description, entity.CreatedBy, entity.SubmittedBy, entity.ApprovedBy, entity.PostedBy, entity.ReversedBy, entity.PostedJournalId, entity.ReversalJournalId, allocated, Math.Max(0m, entity.Amount - allocated), entity.Version); }
    private static FinancePaymentMethodRecord ToMethod(FinancePaymentMethodEntity item) => new(item.Id, item.TenantId.Value, item.CompanyId, item.Code, item.EnglishName, item.ArabicName, item.Direction, item.Lifecycle, item.IsManual, item.RequiresReference, item.EffectiveFrom, item.EffectiveTo, item.Version);
    private static FinanceCashAccountRecord ToCash(FinanceCashAccountEntity item) => new(item.Id, item.TenantId.Value, item.CompanyId, item.Code, item.EnglishName, item.ArabicName, item.Kind, item.CurrencyCode, item.LinkedAccountId, item.LinkedAccountCode, item.BankReference, item.Lifecycle, item.EffectiveFrom, item.EffectiveTo, item.Version);
